import{_ as l,a0 as p,w as r,s as d,ao as o,I as a,x as n,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"使用 WinSCP 將文件和文件夾從 Windows 傳輸到 Linux | LCTT x X-CMD","titleTemplate":false,"description":"使用 WinSCP 將文件和文件夾從 Windows 傳輸到 Linux | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 WinSCP 將文件和文件夾從 Windows 傳輸到 Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 WinSCP 將文件和文件夾從 Windows 傳輸到 Linux | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221101.1 ⭐️⭐️ Transfer files and folders from Windows to Linux with WinSCP","title":"使用 WinSCP 將文件和文件夾從 Windows 傳輸到 Linux","tag":"202211","desc":""},"relativePath":"202211/20221101.1 ⭐️⭐️ Transfer files and folders from Windows to Linux with WinSCP.md","filePath":"[post].md"}'),u={name:"202211/20221101.1 ⭐️⭐️ Transfer files and folders from Windows to Linux with WinSCP.md"};function f(g,s,h,m,w,x){const i=p("Link");return r(),d("div",null,[s[26]||(s[26]=o(`<h1 id="使用-winscp-將文件和文件夾從-windows-傳輸到-linux" tabindex="-1">使用 WinSCP 將文件和文件夾從 Windows 傳輸到 Linux <a class="header-anchor" href="#使用-winscp-將文件和文件夾從-windows-傳輸到-linux" aria-label="Permalink to “使用 WinSCP 將文件和文件夾從 Windows 傳輸到 Linux”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/28/092919hf6y9ojjlmmsfmlm.jpg" alt=""></p><blockquote><p>如果你正在尋找一種快速的從你的 Windows 計算機傳輸文件到你的 Linux 計算機的方法，那麼開源的 WinSCP 實用程序會使其很容易地通過網絡傳輸文件或文件夾。</p></blockquote><p>有時，你需要通過文件傳輸文件。有很多文件共享服務，但是大多數的共享服務都要求你發送你的文件到互聯網上。當兩台計算機並排在一起或在一棟建築物中時，通過互聯網傳輸文件，這似乎看起來繞了很遠的路（更不用説隱私問題）。開源的 WinSCP 實用程序會使其很輕易地通過網絡將一個文件或一個文件夾從你的 Windows 計算機傳輸到你的 Linux 計算機。</p><h3 id="ip-地址" tabindex="-1">IP 地址 <a class="header-anchor" href="#ip-地址" aria-label="Permalink to “IP 地址”">​</a></h3><p>在你可以傳輸之前，你必須知道目標計算機的 IP 地址或完全限定域名。假設它是一台在你的同一個網絡上的計算機，並且你沒有運行 DNS 服務器來解析計算機名稱，你可以在 Linux 計算機上使用 <code>ip</code> 命令來找到目標 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linux]$ ip addr show |grep &#39;inet &#39;</span></span>
<span class="line"><span>inet 127.0.0.1/8 scope host lo  </span></span>
<span class="line"><span>inet 192.168.1.23/24 brd 10.0.1.255 scope global noprefixroute eth0</span></span></code></pre></div><p><code>127.0.0.1</code> 是一個 <ruby>環回地址<rt>loopback address</rt></ruby> ，計算機僅使用它來自我通信，因此在這個示例中，正確的地址是 <code>192.168.1.23</code> 。在你的系統中，IP 地址可能會看起來有所不同。如果你不確定哪個是哪個，你可以逐個嘗試到你找到正確的 IP 地址 （然後，在一些地方寫下來！）</p><p>或者，你可以查找你的路由器設置，它列出了所有通過 DHCP 分配的地址。</p><h3 id="防火牆和地址" tabindex="-1">防火牆和地址 <a class="header-anchor" href="#防火牆和地址" aria-label="Permalink to “防火牆和地址”">​</a></h3><p><code>WinSCP</code> 命令使用 OpenSSH 協議，因此，你的 Linux 計算機必需運行 OpenSSH 服務器軟件，並且你的 Linux 計算機的防火牆必需允許 SSH 通信。</p><p>如果你不確定你的 Linux 機器是否在運行 SSH ，那麼在 Linux 機器的終端上運行這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linux]$ sudo systemctl enable --now sshd</span></span></code></pre></div><p>為確保你的防火牆允許 SSH 通信，運行這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linux]$ sudo firewall-cmd --add-servicessh--permanent</span></span></code></pre></div>`,15)),a("p",null,[s[1]||(s[1]=n("關於 Linux 上的防火牆的更多信息，閲讀 ",-1)),e(i,{href:"https://opensource.com/article/19/7/make-linux-stronger-firewalls"},{default:t(()=>[...s[0]||(s[0]=[n("增強 Linux 防火牆",-1)])]),_:1}),s[2]||(s[2]=n(" 。",-1))]),s[27]||(s[27]=a("h3",{id:"使用-winscp",tabindex:"-1"},[n("使用 WinSCP "),a("a",{class:"header-anchor",href:"#使用-winscp","aria-label":"Permalink to “使用 WinSCP”"},"​")],-1)),a("p",null,[s[5]||(s[5]=n("WinSCP 是一款針對微軟 Windows 的開源 SSH 文件傳輸應用程序。為使用它，你必須先 ",-1)),e(i,{href:"https://sourceforge.net/projects/winscp/files/"},{default:t(()=>[...s[3]||(s[3]=[n("下載",-1)])]),_:1}),s[6]||(s[6]=n(" 和 ",-1)),e(i,{href:"https://sourceforge.net/projects/winscp/files/"},{default:t(()=>[...s[4]||(s[4]=[n("安裝",-1)])]),_:1}),s[7]||(s[7]=n(" 它。",-1))]),s[28]||(s[28]=o(`<p>在你安裝完成後，打開 WinSCP ，並在 “<ruby>文件協議<rt>File Protocol</rt></ruby>” 字段中選擇 “SCP” 選項。</p><p>在 “<ruby>主機名稱<rt>Host name</rt></ruby>” 字段中添加你的 Linux 計算機的 IP 地址或 DNS 名稱，並在 “<ruby>端口號<rt>Port number</rt></ruby>” 字段中輸入 <strong>22</strong> 。針對該 Linux 計算機，輸入你的用户名稱和密碼，然後單擊 WinSCP 窗口底部的 “<ruby>登錄<rt>Login</rt></ruby>” 按鈕。</p><p><img src="https://opensource.com/sites/default/files/2022-10/winscp.loginwindow.png" alt="Image of the WinSCP login window."></p><p>驗證你是否獲取了登錄 Linux 計算機的身份授權。在驗證成功後，你的 Linux 計算機的 IP 地址或 DNS 名稱將顯示在窗口的頂部。</p><p><img src="https://opensource.com/sites/default/files/2022-10/WinSCPwindow.showing.IPinfo.png" alt="Image of a WinSCP window showing where IP adress is located."></p><p>現在，你可以從左側的 Windows 面板中拖拽一個文件（如示例，我使用 <code>winscp-test.txt</code> 文件）到右側的目標 Linux 計算機目標，接下來文件會傳輸。</p><p><img src="https://opensource.com/sites/default/files/2022-10/WinSCP.drapdropwindow.png" alt="Image of drag and drop window in WinSCP."></p><p>或者，你可以在左側的面板中右鍵單擊一個文件，然後上傳它到右側的遠程目標的面板。</p><p><img src="https://opensource.com/sites/default/files/2022-10/RightclickUploadfileWInSCP.png" alt="Image of a right click option to upload files in WinSCP."></p><h3 id="驗證副本" tabindex="-1">驗證副本 <a class="header-anchor" href="#驗證副本" aria-label="Permalink to “驗證副本”">​</a></h3><p>打開一個 Linux 終端，然後使用 <code>ls</code> 命令來查看已傳輸的 <code>winscp-test.txt</code> 文件。在我的示例中，它出現在我的主目錄， <code>/home/sysadmin</code> 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>Desktop</span></span>
<span class="line"><span>Documents</span></span>
<span class="line"><span>Downloads</span></span>
<span class="line"><span>Music</span></span>
<span class="line"><span>Pictures</span></span>
<span class="line"><span>pscp-test.txt[...]</span></span></code></pre></div><p>你已經通過網絡成功地將一個文件從一台 Windows 計算機傳輸到一台 Linux 計算機！</p><p>當然，你也可以使用類似上述的技術，將文件和文件夾從一台 Linux 計算機傳輸到一台 Windows 計算機。</p><h3 id="遠程複製" tabindex="-1">遠程複製 <a class="header-anchor" href="#遠程複製" aria-label="Permalink to “遠程複製”">​</a></h3>`,15)),a("p",null,[s[9]||(s[9]=n("使用強大的開源 WinSCP 應用程序，你可以訪問在你家中或工作場所的任意一台計算機、你擁有賬户的服務器、甚至是移動設備、",-1)),e(i,{href:"https://www.redhat.com/en/topics/edge-computing/what-is-edge-computing?intcmp=7013a000002qLH8AAM"},{default:t(()=>[...s[8]||(s[8]=[n("邊緣設備",-1)])]),_:1}),s[10]||(s[10]=n("、物聯網設備。使用這個極好的工具來傳輸文件就像你在本地目錄下將一個文件複製到另一個本地目錄一樣容易！",-1))]),s[29]||(s[29]=a("hr",null,null,-1)),a("p",null,[s[12]||(s[12]=n("via: ",-1)),e(i,{href:"https://opensource.com/article/22/11/transfer-files-folders-windows-linux-winscp"},{default:t(()=>[...s[11]||(s[11]=[n("https://opensource.com/article/22/11/transfer-files-folders-windows-linux-winscp",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=n("作者：",-1)),e(i,{href:"https://opensource.com/users/plaubscher"},{default:t(()=>[...s[13]||(s[13]=[n("Paul",-1)])]),_:1}),s[18]||(s[18]=n(" 選題：",-1)),e(i,{href:"https://github.com/lkxed"},{default:t(()=>[...s[14]||(s[14]=[n("lkxed",-1)])]),_:1}),s[19]||(s[19]=n(" 譯者：",-1)),e(i,{href:"https://github.com/robsean"},{default:t(()=>[...s[15]||(s[15]=[n("robsean",-1)])]),_:1}),s[20]||(s[20]=n(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[16]||(s[16]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[23]||(s[23]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[21]||(s[21]=[n("LCTT",-1)])]),_:1}),s[24]||(s[24]=n(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[22]||(s[22]=[n("Linux中國",-1)])]),_:1}),s[25]||(s[25]=n(" 榮譽推出",-1))])])}const C=l(u,[["render",f]]);export{k as __pageData,C as default};
